import{_ as n,o as e,c as i,a6 as r}from"./chunks/framework.DycQjAfF.js";const g=JSON.parse('{"title":"Riwayat Versi","description":"Catatan perubahan handbook dari versi ke versi.","frontmatter":{"title":"Riwayat Versi","description":"Catatan perubahan handbook dari versi ke versi.","status":"ditinjau","diperbarui":"2026-10-20T00:00:00.000Z","kategori":"Tentang Handbook","kata_kunci":["versi","riwayat","changelog","perubahan"]},"headers":[],"relativePath":"tentang-handbook/riwayat-versi.md","filePath":"tentang-handbook/riwayat-versi.md"}'),t={name:"tentang-handbook/riwayat-versi.md"};function o(l,a,s,u,k,d){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="riwayat-versi" tabindex="-1">Riwayat Versi <a class="header-anchor" href="#riwayat-versi" aria-label="Permalink to &quot;Riwayat Versi&quot;">​</a></h1><p class="lead">Setiap perubahan penting dicatat di sini. Nomor versi juga tercantum di menu atas dan di <code>package.json</code>.</p><h2 id="v0-4-1-22-oktober-2026" tabindex="-1">v0.4.1 (22 Oktober 2026) <a class="header-anchor" href="#v0-4-1-22-oktober-2026" aria-label="Permalink to &quot;v0.4.1 (22 Oktober 2026)&quot;">​</a></h2><ul><li><p><strong>STTB tidak dipakai lagi.</strong> Langkah &quot;STTB diberikan ke vendor&quot; dihapus dari alur barang masuk, lalu urutannya menjadi GRN terbit (langkah 6) dan input ke database (langkah 7). Alur barang masuk sekarang 9 langkah. Foto flowchart ikut digeser ke nomor barunya.</p></li><li><p>SOP Penerimaan Barang, flowchart Alur Warehouse, Kamus Istilah, Pencatatan Stok, FAQ, dan beranda ikut disesuaikan.</p></li><li><p><strong>Keluar selalu kembali ke Beranda.</strong> Setelah menekan Keluar dari halaman mana pun, website kembali ke Beranda di balik layar login, sehingga login berikutnya selalu dimulai dari Beranda.</p></li><li><p><strong>Tampilan HP diperbaiki.</strong> Header tidak lagi lebih lebar dari layar (sisi kanan tidak kosong lagi dan halaman tidak bisa di-zoom out melebihi layar): judul dibuat dua baris di HP, dan tombol Keluar pindah ke menu ☰. Tautan di menu ☰ yang sebelumnya putih di atas putih kini terbaca, dan kata panjang di kotak &quot;Tidak&quot; pada flowchart boleh dipatahkan. Semua halaman diperiksa di lebar 320, 360, 375, 390, dan 412 px.</p></li><li><p><strong>Halaman baru: Kegiatan Rutin</strong> di menu Mulai. Isinya linimasa satu minggu kerja (Senin sampai Jumat) dengan penanda &quot;Hari ini&quot;: meeting setiap Rabu, kerja bakti setiap Kamis, dan stock opname harian, lengkap dengan hal yang perlu disiapkan.</p></li><li><p>Jadwal diatur lewat <code>docs/data/kegiatan.json</code>. Jam dan tempat masih menunggu konfirmasi pembimbing.</p></li><li><p>Setiap kartu kegiatan punya slot foto (3 untuk meeting dan kerja bakti, 2 untuk stock opname harian). Fotonya ditaruh di <code>docs/public/images/kegiatan/</code>.</p></li><li><p>Panduan Magang Baru, FAQ, Yang Perlu Dikonfirmasi, dan Cara Memperbarui Handbook ikut diperbarui.</p></li></ul><h2 id="v0-4-0-20-oktober-2026" tabindex="-1">v0.4.0 (20 Oktober 2026) <a class="header-anchor" href="#v0-4-0-20-oktober-2026" aria-label="Permalink to &quot;v0.4.0 (20 Oktober 2026)&quot;">​</a></h2><ul><li><strong>Login tampilan</strong> tanpa backend: seluruh website terkunci sampai pengunjung masuk, browser mengingat login selama 7 hari, dan ada tombol <strong>Keluar</strong> di menu atas.</li><li>Akun diatur dengan <code>npm run atur-login</code>. Kata sandi disimpan sebagai hash, bukan teks asli.</li><li><strong>Transisi setelah login</strong>: panel navy melebar menutup layar, lalu menyusut menjadi kotak sambutan beranda, dan animasi beranda menyambung. Di halaman lain, panel menyusut ke header.</li><li>Checklist Publikasi dan Cara Memperbarui Handbook menjelaskan batasan login ini.</li></ul><h2 id="v0-3-2-20-oktober-2026" tabindex="-1">v0.3.2 (20 Oktober 2026) <a class="header-anchor" href="#v0-3-2-20-oktober-2026" aria-label="Permalink to &quot;v0.3.2 (20 Oktober 2026)&quot;">​</a></h2><ul><li>Laporan barang masuk ke divisi OS/PPIC dihapus dari alur, SOP, FAQ, dan Kamus Istilah, karena Gudang Teknik tidak melapor ke divisi tersebut.</li><li>Diagram &quot;Dengan siapa gudang bekerja?&quot; kini menampilkan laboratorium dan buyer procurement/purchasing.</li><li>Tabel catatan di halaman Pencatatan Stok disesuaikan dengan instruksi kerja (STTB, GRN, reservasi, kartu stok, dan stock opname harian).</li><li>Foto GRN ditambahkan di langkah 8 alur barang masuk dan sebagai contoh di SOP Penerimaan Barang.</li></ul><h2 id="v0-3-1-20-oktober-2026" tabindex="-1">v0.3.1 (20 Oktober 2026) <a class="header-anchor" href="#v0-3-1-20-oktober-2026" aria-label="Permalink to &quot;v0.3.1 (20 Oktober 2026)&quot;">​</a></h2><p>Alur kerja disamakan dengan instruksi kerja resmi dari perusahaan. Jumlah dan urutan langkah tetap, sehingga foto yang sudah ada tetap cocok.</p><ul><li><strong>Alur barang masuk</strong> mengikuti Instruksi Kerja Penerimaan Material: cek dokumen dan pesanan, area inspeksi, pemeriksaan oleh gudang, laboratorium, atau user, Material Reject, STTB, GRN, penyimpanan sesuai klasifikasi, dan kartu stok.</li><li><strong>Alur barang keluar</strong> mengikuti Instruksi Kerja Pelayanan Barang: reservasi dan persetujuan Foreman/Supervisor, potong stok di sistem, cetak reservasi, batas 3 hari di rak reservasi, dan <strong>verifikasi NIP</strong> sebagai titik pengecekan baru (tempat foto baru <code>barang-keluar-09-tidak</code>).</li><li>Flowchart Alur Warehouse, nomor langkah SOP Penerimaan Barang, dan teks beranda ikut diselaraskan.</li></ul><h2 id="v0-3-0-20-oktober-2026" tabindex="-1">v0.3.0 (20 Oktober 2026) <a class="header-anchor" href="#v0-3-0-20-oktober-2026" aria-label="Permalink to &quot;v0.3.0 (20 Oktober 2026)&quot;">​</a></h2><p>Isi SOP dan materi Gudang Teknik diselaraskan dengan dokumen resmi: Kumpulan Instruksi Kerja &amp; Standard Gudang Teknik dan Prosedur Penghapusbukuan Aktiva Tetap (Write Off) QP-4.3.3.</p><ul><li><strong>SOP ditulis ulang dari instruksi kerja</strong>: penerimaan (siapa memeriksa apa, STTB, GRN, Material Reject), penyimpanan (penempatan per klasifikasi, FIFO dan FEFO, Gudang B3), pengeluaran (reservasi, persetujuan Foreman/Supervisor, verifikasi NIP, batas 3 hari), dan stock opname harian bergilir.</li><li><strong>SOP baru: Permintaan Kode Material Baru</strong> untuk stock item dan non-stock item.</li><li><strong>SOP Write Off</strong> mengikuti prosedur QP-4.3.3, lengkap dengan alur, peran, dan format nomor surat.</li><li><strong>Kode Barang dan tutorialnya</strong> memakai struktur nomor material resmi 9 karakter (material type, group, sub group, nomor urut) dan format deskripsi material.</li><li>Langkah flowchart barang masuk dan keluar, Manajemen Stok, Alur Stock Opname, K3 (APD dan Gudang B3), Kamus Istilah, FAQ, dan daftar sumber ikut diperbarui.</li></ul><p>Sejak v0.2.1 juga ada perubahan tampilan: tema navy, oranye, dan putih, logo BPI, beranda baru dengan animasi dan parallax, denah gudang, foto alur dan profil perusahaan, serta tampilan yang menyesuaikan monitor lebar.</p><h2 id="v0-2-1-13-oktober-2026" tabindex="-1">v0.2.1 (13 Oktober 2026) <a class="header-anchor" href="#v0-2-1-13-oktober-2026" aria-label="Permalink to &quot;v0.2.1 (13 Oktober 2026)&quot;">​</a></h2><ul><li><strong>Tempat foto di setiap kotak flowchart</strong> barang masuk dan barang keluar, termasuk kotak &quot;Tidak&quot;. Selama foto belum ada, yang tampil placeholder.</li><li>Kotak flowchart diberi nomor yang sama dengan kartu langkah. Kotak bernomor bisa diklik untuk melompat ke kartu fotonya.</li><li>Langkah dipecah agar satu kotak flowchart sama dengan satu kartu: barang masuk 10 langkah, barang keluar 11 langkah.</li><li>Daftar nama file foto dan statusnya ada di halaman Cara Memperbarui Handbook.</li></ul><h2 id="v0-2-0-13-oktober-2026" tabindex="-1">v0.2.0 (13 Oktober 2026) <a class="header-anchor" href="#v0-2-0-13-oktober-2026" aria-label="Permalink to &quot;v0.2.0 (13 Oktober 2026)&quot;">​</a></h2><p>Tampilan dibuat lebih sederhana dan ramah, serta alur kerja disesuaikan dengan alur asli Gudang Teknik.</p><ul><li><strong>Alur barang masuk dan barang keluar</strong> sekarang mengikuti diagram presentasi dan catatan alur proses Gudang Teknik (ERP, rak reservasi, catatan manual rak, surat tanda terima, laporan ke OS/PPIC).</li><li><strong>Flowchart baru</strong>: alur warehouse lengkap, barang masuk, dan barang keluar, berwarna sesuai pelaku, ditambah daftar langkah bernomor.</li><li><strong>Beranda baru</strong>: kolom pencarian, enam topik utama, dan tiga langkah untuk peserta baru.</li><li><strong>Lebih sederhana</strong>: label status, catatan kaki sumber, tombol kata kunci, filter FAQ, tabel identitas SOP, dan menu versi dihapus dari tampilan. Menu atas tinggal empat.</li><li><strong>Font Plus Jakarta Sans</strong>, sudut kartu lebih bulat, dan bahasa disapa dengan &quot;kamu&quot;.</li><li>SOP Penerimaan dan Pengeluaran Barang ditulis ulang sesuai alur asli. FAQ dan Kamus Istilah ditambah (ERP, OS/PPIC, rak reservasi, surat tanda terima, catatan manual rak).</li></ul><h2 id="v0-1-0-13-oktober-2026" tabindex="-1">v0.1.0 (13 Oktober 2026) <a class="header-anchor" href="#v0-1-0-13-oktober-2026" aria-label="Permalink to &quot;v0.1.0 (13 Oktober 2026)&quot;">​</a></h2><p>Versi awal untuk ditinjau pembimbing.</p><ul><li>Struktur website: Beranda, Profil Perusahaan, Gudang Teknik, Alur Kerja, Tutorial, SOP, FAQ, Referensi, dan halaman 404.</li><li>Profil perusahaan dari sumber publik, dengan status verifikasi per bagian. Visi, misi, sejarah, dan struktur organisasi belum ditampilkan karena belum ada sumber resmi.</li><li>Materi Gudang Teknik dari presentasi internal: pengertian, fungsi, jenis material, manajemen inventory, kode barang, administrasi stok, dan indikator kinerja.</li><li>Alur barang masuk, barang keluar, dan stock opname sebagai <strong>draf</strong>. Alur ini belum dicocokkan dengan gambar slide 5–6.</li><li>Enam SOP draf dari praktik umum pergudangan.</li><li>Empat tutorial dengan data latihan.</li><li>Pencarian lokal, breadcrumb, daftar isi, diagram, FAQ accordion, dan tampilan responsif.</li></ul><h2 id="cara-mencatat-versi-baru" tabindex="-1">Cara mencatat versi baru <a class="header-anchor" href="#cara-mencatat-versi-baru" aria-label="Permalink to &quot;Cara mencatat versi baru&quot;">​</a></h2><ol><li>Naikkan nomor <code>version</code> di <code>package.json</code>. Gunakan angka tengah untuk penambahan isi (0.2.0) dan angka akhir untuk perbaikan kecil (0.1.1).</li><li>Tambahkan bagian baru di atas halaman ini, berisi tanggal dan daftar perubahannya.</li></ol>',25)])])}const b=n(t,[["render",o]]);export{g as __pageData,b as default};
